-- Generated by noctus.dev.scaffold_migration on 2026-10-19
-- Schema: social_wiring


-- ============================================================
-- The representative's OWN CRECI on an intermediário (deal 876, 2026-10-19)
-- ============================================================
-- WHY: a PJ intermediary (a brokerage) is qualified in the corretagem clause
-- by its CNPJ + CRECI-J and "neste ato representada por" a partner — and the
-- signed contract qualifies that partner by HER OWN CRECI too: "COCCI IMÓVEIS
-- LTDA ... CRECI 040242-J, neste ato representada por sua sócia Ana Maria
-- Cocci, ..., corretora de imóveis, Creci 145830-F 2ª região". 114 gave the
-- representative a name and a CPF but no CRECI, so the generated clause
-- could never carry it (the last material diff of deal 876's cl.13 besides
-- the owner's Q5 % decision). The office's own intermediação already has the
-- same pair on the org row (`responsavel_creci` / `_regiao`); this mirrors it.
--
-- No document carries it today (a manual-input field, like 114's): the
-- service validates `representante_creci` with the seed's CRECI reader
-- (`identificador.validar_creci`) and requires the PRINTED F suffix — a
-- person's CRECI, never a J — then stores the canonical form. Not personal
-- data beyond a professional registration number (public CRECI register).
ALTER TABLE social_wiring.atendimento_intermediarios
    ADD COLUMN IF NOT EXISTS representante_creci        TEXT,
    ADD COLUMN IF NOT EXISTS representante_creci_regiao TEXT;

COMMENT ON COLUMN social_wiring.atendimento_intermediarios.representante_creci IS
    'CRECI-F of the representative signing for a PJ intermediary (285), '
    'canonical "NNNNNN-F[/UF]" — validated by the service (F suffix required).';
COMMENT ON COLUMN social_wiring.atendimento_intermediarios.representante_creci_regiao IS
    'Region the representative''s CRECI is printed with ("2ª região"), free '
    'text, rendered beside it (285).';
